const raw = items[0].json;
const body = raw.body || raw;
const headers = raw.headers || {};
const headerSecret = headers['x-wakeup-secret'] || headers['X-Wakeup-Secret'] || '';
const bodySecret = body.webhook_secret || '';
// 匯入後若要鎖定公開 webhook，把下一行改成實際密鑰；維持空字串則不驗證（相容舊流程）。
const SHARED_SECRET = '';
if (SHARED_SECRET) {
  const got = String(headerSecret || bodySecret || '').trim();
  if (got !== SHARED_SECRET) {
    return [{ json: { skip: true, ok: false, reason: 'unauthorized' } }];
  }
}
const email = String(body.customer_email || body.user_email || '').trim();
const text = String(body.message_text || body.status_message || '').trim();
const name = body.customer_name || '顧客';
const subject = body.subject || 'T&J 關心您上次的訂購';
if (!email || !text) {
  return [{ json: { skip: true, ok: false, reason: 'missing email or text' } }];
}
const escapeHtml = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');
const safeText = escapeHtml(text).replace(/\n/g, '<br/>');
return [{
  json: {
    skip: false,
    ok: true,
    customer_email: email,
    subject,
    message_text: text,
    customer_name: name,
    html: `<p>${safeText}</p><p style="color:#888;font-size:12px">— T&J Cookies</p>`
  }
}];
